def certify_profit_giveback_route_source(*, source_overrides=None):
    """Fail closed if any reviewed arming, order or persistence route changes."""
    overrides = source_overrides or {}
    if set(overrides) - set(REVIEWED_PROFIT_ROUTE):
        raise ValueError('Profit route override is outside reviewed authority')
    root = Path(__file__).parents[2]
    observed = []
    for relative, expected in REVIEWED_PROFIT_ROUTE.items():
        source = Path(overrides.get(relative, root / relative)).read_text(encoding='utf-8')
        classifier_symbols = {
            'src/backend/backtest_declared_ladder_plan.py': ('automatic_policy',),
            'src/backend/backtest_ladder_source_authority.py': ('declared_ladder_policy',),
            'src/trading_runtime/squeeze_ladder_automatic.py': ('AutomaticLadderPolicy',),
        }
        if relative in classifier_symbols and (type(expected) is not dict or tuple(expected) != classifier_symbols[relative]):
            raise ValueError('Closed classifier source selector shape changed: '+relative)
        kinds = ('ClassDef',) if relative == 'src/trading_runtime/squeeze_ladder_automatic.py' else ('FunctionDef','AsyncFunctionDef')
        summaries = canonical_symbol_ast_summary(source, tuple(expected), kinds=kinds)
        if len(summaries) != len(expected):
            raise ValueError('Strategy 31 source summary shape changed: ' + relative)
        for (name, digest), summary in zip(expected.items(), summaries):
            if summary.name != name or len(summary.digests) != 1:
                raise ValueError('Strategy 31 reviewed profit-route authority changed: ' + relative + ':' + name)
            if summary.digests[0] != digest:
                from .backtest_fixed_v4_certification import _reviewed_fixed_lot_profit_projection
                if not _reviewed_fixed_lot_profit_projection(source, relative, name, digest):
                    raise ValueError('Strategy 31 reviewed profit-route authority changed: ' + relative + ':' + name)
        observed.append((relative, sha256(source.encode()).hexdigest()))
    return sha256(json.dumps(observed, separators=(',', ':')).encode()).hexdigest()
